customCss:
.v-app-bar .v-toolbar-title__placeholder::after { content: " 🦃"; }
.v-app-bar { border-bottom: 3px solid rgb(var(--v-theme-accent)); }

/* 🍂 Falling leaves */
.v-application::before,
.v-application::after {
  position: fixed;
  top: -10vh;
  left: 0;
  width: 100vw;
  pointer-events: none;
  z-index: 3000;
  white-space: pre;
  font-size: 22px;
  opacity: 0.7;
  animation: mealie-fall 18s linear infinite;
}
.v-application::before {
  content: "🍂            🍁                     🍂          🍁                🍂                 🍁         🍂";
}
.v-application::after {
  content: "      🍁                 🍂          🍁                    🍂            🍁        🍂             🍁";
  font-size: 18px;
  animation-duration: 24s;
  animation-delay: -9s;
}
@keyframes mealie-fall {
  0%   { transform: translate(0, 0) rotate(0deg); }
  50%  { transform: translate(30px, 60vh) rotate(8deg); }
  100% { transform: translate(-20px, 125vh) rotate(-6deg); }
}
@media (prefers-reduced-motion: reduce) {
  .v-application::before, .v-application::after { animation: none; display: none; }
}
